    u_vertDeform:U({value:{incline:U({value:.5}),offsetTop:U({value:-.5}),offsetBottom:U({value:-.5}),noiseFreq:U({value:[3,4],type:'vec2'}),noiseAmp:U({value:250}),noiseSpeed:U({value:10}),noiseFlow:U({value:5}),noiseSeed:U({value:5})},type:'struct',excludeFrom:'fragment'}),
