/* ---------- Ring play button (The longer read, Industries): plays from load until the button turns it off.
   The ring's animationend advances, so holding the ring while the section is off-screen holds the tour too.
   Returns restart(), which callers run after any manual change so the ring starts over. ---------- */
function ringPlay(btn,next,watch,ms){
  const bar=btn.querySelector('.bar'),lab=btn.querySelector('.lab'),reduce=matchMedia('(prefers-reduced-motion: reduce)').matches;
  let on=true,vis=false,tm=0;btn.style.setProperty('--lr-ms',ms+'ms');
  const label=()=>{btn.classList.toggle('paused',!on);lab.textContent=on?'Pause':btn.dataset.play};
  const hold=()=>btn.classList.toggle('held',!vis);
  const restart=()=>{clearTimeout(tm);btn.classList.remove('run');if(!on)return;void btn.offsetWidth;btn.classList.add('run');
    // reduced motion switches animations off, so a timer advances instead (and waits while off-screen)
    if(reduce)tm=setTimeout(function tick(){if(vis)next();else tm=setTimeout(tick,ms)},ms)};
  bar.addEventListener('animationend',()=>{if(on)next()});
  btn.addEventListener('click',()=>{on=!on;label();restart()});
  new IntersectionObserver(([e])=>{vis=e.isIntersecting;hold()},{threshold:.2}).observe(watch);
  label();hold();restart();return restart}

