/* ---------- Team holo cards: spring-driven tilt / light engine ported from React Bits ProfileCard ---------- */
{const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches,TILT=10,DEPTH=8,clamp=(v,a,b)=>Math.min(b,Math.max(a,v));
 document.querySelectorAll('#teamGrid .flip').forEach((root,i)=>{
  const size={w:root.offsetWidth,h:root.offsetHeight},x={p:0,v:0,target:0},y={p:0,v:0,target:0},light={p:0,target:0};
  let raf=0,last=0,slowUntil=0,touchId=null;
  const write=()=>{const ang=reduced?0:TILT,tilt=Math.min(1,Math.hypot(x.p,y.p)),s=root.style;
    s.setProperty('--pc-light-x',((x.p+1)*.5*size.w).toFixed(1)+'px');s.setProperty('--pc-light-y',((y.p+1)*.5*size.h).toFixed(1)+'px');
    s.setProperty('--pc-pointer-x',((x.p+1)*50).toFixed(2)+'%');s.setProperty('--pc-pointer-y',((y.p+1)*50).toFixed(2)+'%');
    s.setProperty('--pc-band-x',(50+x.p*15).toFixed(2)+'%');s.setProperty('--pc-band-y',(50+y.p*15).toFixed(2)+'%');
    s.setProperty('--pc-rotate-x',(y.p*ang).toFixed(3)+'deg');s.setProperty('--pc-rotate-y',(-x.p*ang).toFixed(3)+'deg');
    s.setProperty('--pc-shift-x',(x.p*(reduced?0:DEPTH)).toFixed(2)+'px');s.setProperty('--pc-shift-y',(y.p*(reduced?0:DEPTH)).toFixed(2)+'px');
    s.setProperty('--pc-tilt',(tilt*light.p).toFixed(4));s.setProperty('--pc-active',light.p.toFixed(4))};
  const frame=now=>{const dt=Math.min(.05,(now-last)/1000||0);last=now;const slow=now<slowUntil,k=slow?24:120,c=slow?9:16,steps=Math.max(1,Math.ceil(dt*120)),h=dt/steps;
    for(let n=0;n<steps;n++)for(const a of [x,y]){a.v+=(k*(a.target-a.p)-c*a.v)*h;a.p+=a.v*h}
    const tau=light.target>light.p?.18:slow?.9:.45;light.p+=(light.target-light.p)*(1-Math.exp(-dt/tau));write();
    const moving=Math.abs(x.target-x.p)>5e-4||Math.abs(y.target-y.p)>5e-4||Math.abs(x.v)>5e-4||Math.abs(y.v)>5e-4||Math.abs(light.target-light.p)>.002;
    if(moving)raf=requestAnimationFrame(frame);else{x.p=x.target;y.p=y.target;light.p=light.target;write();raf=0}};
  const wake=()=>{if(raf)return;last=performance.now();raf=requestAnimationFrame(frame)};
  const aim=(nx,ny,on=true)=>{x.target=clamp(nx,-1,1);y.target=clamp(ny,-1,1);light.target=on?1:0;slowUntil=0;wake()};
  const aimAt=e=>{const r=root.getBoundingClientRect();if(r.width&&r.height)aim((e.clientX-r.left)/r.width*2-1,(e.clientY-r.top)/r.height*2-1)};
  const release=()=>aim(0,0,false);
  root.addEventListener('pointerenter',e=>{if(e.pointerType==='mouse')aimAt(e)});
  root.addEventListener('pointermove',e=>{if(e.pointerType==='mouse'||e.pointerId===touchId)aimAt(e)});
  root.addEventListener('pointerleave',e=>{if(e.pointerType==='mouse')release()});
  root.addEventListener('pointerdown',e=>{if(e.pointerType!=='mouse'){touchId=e.pointerId;aimAt(e)}});
  const up=e=>{if(e.pointerId===touchId){touchId=null;release()}};root.addEventListener('pointerup',up);root.addEventListener('pointercancel',up);
  new ResizeObserver(()=>{size.w=root.offsetWidth;size.h=root.offsetHeight;write()}).observe(root);
  write();
  // intro: each card catches the light once, just after its pixel reveal has finished
  if(!reduced)new IntersectionObserver((es,io)=>{if(!es[0].isIntersecting)return;io.disconnect();
    setTimeout(()=>{if(light.target)return;x.p=.62;y.p=-.55;light.p=1;slowUntil=performance.now()+1400;write();wake()},1500+i*140)},{threshold:.35}).observe(root);
 });}

/* ---------- Team: each photo reveals itself through a diagonal sweep of pixels when it scrolls into view ---------- */
{const paper=getComputedStyle(document.documentElement).getPropertyValue('--paper-2').trim()||'#efe7d8';
 const CELL=14,HOLD=.22,SPAN=1.1; // px per pixel block · seconds a block shows the mosaic · seconds the sweep takes to cross
 const pixelReveal=(ph,delay)=>{const img=ph.querySelector('img'),cv=document.createElement('canvas'),ctx=cv.getContext('2d'),sm=document.createElement('canvas'),sc=sm.getContext('2d');
   cv.className='pxr';cv.setAttribute('aria-hidden','true');
   let W,H,cols,D,t0=-1;
   const size=()=>{const r=Math.min(devicePixelRatio||1,2);W=ph.offsetWidth;H=ph.offsetHeight;cv.width=W*r;cv.height=H*r;ctx.setTransform(r,0,0,r,0,0);
     cols=Math.ceil(W/CELL);const rows=Math.ceil(H/CELL);sm.width=cols;sm.height=rows;
     // the mosaic is the photo drawn tiny with the same cover / top crop and filter as the <img>, then scaled up unsmoothed
     const iw=img.naturalWidth,ih=img.naturalHeight,s=Math.max(cols*CELL/iw,rows*CELL/ih),sw=cols*CELL/s,sh=rows*CELL/s;
     sc.filter='saturate(.85) sepia(.1)';sc.drawImage(img,(iw-sw)/2,0,sw,sh,0,0,cols,rows);
     D=new Float32Array(cols*rows);
     for(let y=0;y<rows;y++)for(let x=0;x<cols;x++)D[y*cols+x]=((x/cols)*.55+(y/rows)*.45)*SPAN+Math.random()*.25};
   let run=0,tm=0,state='covered'; // covered → playing → shown; leaving the viewport entirely re-covers it for the next visit
   const draw=(id,now)=>{if(id!==run)return;const t=t0<0?-1:(now-t0)/1000;ctx.clearRect(0,0,W,H);ctx.imageSmoothingEnabled=false;let left=0;
     for(let i=0;i<D.length;i++){const cx=i%cols,cy=i/cols|0,e=t-D[i];if(e>=HOLD)continue;left++;
       if(e<0){ctx.fillStyle=paper;ctx.fillRect(cx*CELL,cy*CELL,CELL,CELL)}else ctx.drawImage(sm,cx,cy,1,1,cx*CELL,cy*CELL,CELL,CELL)}
     if(!left){cv.remove();state='shown'}else if(t0>=0)requestAnimationFrame(n=>draw(id,n))};
   const cover=()=>{clearTimeout(tm);run++;t0=-1;ph.append(cv);size();draw(run,performance.now());state='covered'};
   const play=()=>{state='playing';tm=setTimeout(()=>{const id=++run;t0=performance.now();requestAnimationFrame(n=>draw(id,n))},delay)};
   const start=()=>{cover();
     new IntersectionObserver(([e])=>{
       if(e.intersectionRatio>=.35&&state==='covered')play();
       else if(!e.isIntersecting&&state!=='covered')cover()},{threshold:[0,.35]}).observe(ph)};
   // the photo stays plainly visible if it never loads
   if(img.complete&&img.naturalWidth)start();else img.addEventListener('load',start,{once:true})};
 if(!matchMedia('(prefers-reduced-motion: reduce)').matches)document.querySelectorAll('#teamGrid .ph').forEach((ph,i)=>pixelReveal(ph,i*140));}

