  const ctx=cv.getContext('2d'),reduce=matchMedia('(prefers-reduced-motion: reduce)').matches;
  const rgb=(()=>{const t=document.createElement('canvas').getContext('2d');t.fillStyle='#fff';t.fillStyle=o.glowColor;const h=t.fillStyle;return[1,3,5].map(i=>parseInt(h.slice(i,i+2),16))})();
  const clamp=(v,a,b)=>Math.min(Math.max(v,a),b),ss=(a,b,v)=>{const t=clamp((v-a)/(b-a),0,1);return t*t*(3-2*t)},back=t=>{const u=t-1;return 1+2.9*u*u*u+1.9*u*u};
  const S={w:0,h:0,r:1,n:0,act:false,ch:0,t:0,last:0,raf:0,vis:true,ox:0,oy:0,far:1,px:0,py:0,sx:0,sy:0,vx:0,vy:0,sp:0,hov:false,pulses:[],dt:1/60,rel:-1,intro:-1};
  const sched=()=>{const span=o.revealDuration/1000;let far=1;
    for(let i=0;i<S.n;i++)far=Math.max(far,Math.hypot(S.X[i]-S.ox,S.Y[i]-S.oy));S.far=far;
    for(let i=0;i<S.n;i++){const d=Math.hypot(S.X[i]-S.ox,S.Y[i]-S.oy)/far;S.D[i]=S.act?d*span*.82+S.J[i]*span*.18:(1-d)*span*.45+S.J[i]*span*.1}};
