    if(w===S.w&&h===S.h&&r===S.r)return;Object.assign(S,{w,h,r});cv.width=Math.round(w*r);cv.height=Math.round(h*r);
    const g=o.gap,cols=Math.floor((w-1)/g)+1,rows=Math.floor((h-1)/g)+1,offx=(w-(cols-1)*g)/2,offy=(h-(rows-1)*g)/2,n=cols*rows,F=()=>new Float32Array(n);
