/* ---------- Section fields (WebGL2). Insights = ink: pigment flowing in water, fine tide lines where it pools, gathering
   toward the reader's cursor and taking a breath when the next question is asked. Team = silk: long folds of cloth lit
   by a light that follows the cursor. Both: stirred a little by scrolling, calmest in the middle where the content sits,
   paused off-screen and in hidden tabs, one still frame for reduced motion. ---------- */
const SX_VS=`#version 300 es
in vec2 p;void main(){gl_Position=vec4(p,0.,1.);}`;
const SX_FS=`#version 300 es
precision highp float;out vec4 o;uniform vec2 R,P;uniform float T,M,B;uniform vec3 C0,C1,C2,C3,W;
float h(vec2 p){return fract(sin(dot(p,vec2(127.1,311.7)))*43758.5453);}
float n(vec2 p){vec2 i=floor(p),f=fract(p),u=f*f*(3.-2.*f);return mix(mix(h(i),h(i+vec2(1,0)),u.x),mix(h(i+vec2(0,1)),h(i+vec2(1,1)),u.x),u.y);}
float fbm(vec2 p){float v=0.,a=.5;for(int i=0;i<5;i++){v+=a*n(p);p=p*2.03+vec2(1.7,9.2);a*=.5;}return v;}
float fbm3(vec2 p){float v=0.,a=.5;for(int i=0;i<3;i++){v+=a*n(p);p=p*2.03+vec2(1.7,9.2);a*=.5;}return v/.875;} // fewer octaves: long, smooth folds
vec3 ink(vec2 uv){vec2 a=vec2(R.x/R.y,1.),p=uv*a*1.5,c=P*a*1.5;float t=T*.05;
 float d=length(p-c),pull=exp(-d*d*1.6)*(.35+B*.9);
 vec2 q=vec2(fbm(p+vec2(t,-t*.7)),fbm(p+vec2(5.2,1.3)-vec2(t*.8,t*.5)));
 float f=fbm(p+(2.4+B*1.4)*q+(c-p)*pull*.6+vec2(t*.5,-t*.3));
 vec3 col=mix(C0,C1,smoothstep(.3,.8,f));col=mix(col,C2,smoothstep(.5,.95,q.x)*.85);col=mix(col,C3,smoothstep(.55,1.,q.y)*.7);
 float fw=fwidth(f)*1.6+.003,tide=1.-smoothstep(0.,fw,abs(f-.58)),tide2=1.-smoothstep(0.,fw,abs(f-.44));
 return mix(col,col*vec3(.86,.88,.9),tide*.55+tide2*.3);}
vec3 silk(vec2 uv){vec2 a=vec2(R.x/R.y,1.),s=uv*a*vec2(.55,1.5);float t=T*.05;
 vec2 q=vec2(fbm3(s+vec2(t*.6,t*.2)),fbm3(s+vec2(4.1,2.3)-vec2(t*.4,0.)));float f=fbm3(s+1.5*q+vec2(0.,t*.3));
 vec3 nr=normalize(vec3(-vec2(dFdx(f),dFdy(f))*R.y*.55,1.)),L=normalize(vec3((P-.5)*vec2(2.2,1.6),.9));
 float diff=dot(nr,L)*.5+.5,spec=pow(max(dot(reflect(-L,nr),vec3(0,0,1)),0.),20.)*.45; // a soft glint, never a blown-out patch
 vec3 col=mix(C0,C1,smoothstep(.25,.85,f));col=mix(col,C2,smoothstep(.55,.95,q.x)*.55);col=mix(col,C3,smoothstep(.5,1.,q.y)*.45);
 return min(col*(.88+.12*diff)+spec*.16*vec3(1.,.98,.94),vec3(.985));}
vec3 plume(vec2 uv){float a=R.x/R.y,t=T*.05;vec3 col=C0; // three emission plumes, Scope 1 · 2 · 3, left to right
 for(int i=0;i<3;i++){float fi=float(i),y=uv.y,cx=.17+.33*fi;
  float sway=(fbm(vec2(fi*3.1,y*1.4-t*.8))-.5)*.22*(.3+y),w=(.05+.16*y)/sqrt(a/1.6); // sways in the air, widens as it rises
  float d=uv.x-cx-sway,body=exp(-(d*d)/(w*w));
  float turb=fbm(vec2(uv.x*a*3.+fi*7.,y*2.6-t*1.4)); // billows travel upward
  float k=body*smoothstep(-.05,.25,y)*(1.-smoothstep(.72,1.02,y))*smoothstep(.35,.75,turb+.15*body);
  vec3 cc=i==0?C1:(i==1?C2:C3);float wt=i==0?W.x:(i==1?W.y:W.z);
  col=mix(col,cc,k*(.14+.52*wt));} // the selected scope's plume swells and deepens
 return col;}
void main(){vec2 uv=gl_FragCoord.xy/R;vec3 c=M<.5?ink(uv):(M<1.5?silk(uv):plume(uv));
 c=mix(c,C0,.25*smoothstep(.95,.2,length((uv-.5)*vec2(1.,.9)))); // calmest in the middle, where the content sits
 o=vec4(c,1.);}`;
const SX_PAL={ // [ground, colour 1, colour 2, colour 3] as 0-1 RGB from the page palette
 insights:[[.937,.918,.875],[.788,.847,.902],[.918,.839,.678],[.725,.804,.714]], // paper · sky · sand · sage
 team:[[.925,.937,.898],[.722,.812,.71],[.89,.725,.651],[.765,.831,.902]],       // paper · sage · clay · sky
 solutions:[[.937,.906,.847],[.784,.451,.353],[.851,.643,.255],[.31,.427,.604]]}; // paper · Scope 1 clay · Scope 2 ochre · Scope 3 indigo
function sxField(sec,mode){
  const host=sec&&sec.querySelector('.sx-bg');if(!host)return;
  const cv=document.createElement('canvas');cv.className='sx-gl';host.prepend(cv);
  const gl=cv.getContext('webgl2',{antialias:false,alpha:false});if(!gl)return; // no WebGL2: the panel keeps its flat paper colour
  const sh=(type,src)=>{const s=gl.createShader(type);gl.shaderSource(s,src);gl.compileShader(s);
    if(!gl.getShaderParameter(s,gl.COMPILE_STATUS))console.warn('sxField shader:',gl.getShaderInfoLog(s));return s};
  const pg=gl.createProgram();gl.attachShader(pg,sh(gl.VERTEX_SHADER,SX_VS));gl.attachShader(pg,sh(gl.FRAGMENT_SHADER,SX_FS));gl.linkProgram(pg);gl.useProgram(pg);
  gl.bindBuffer(gl.ARRAY_BUFFER,gl.createBuffer());gl.bufferData(gl.ARRAY_BUFFER,new Float32Array([-1,-1,3,-1,-1,3]),gl.STATIC_DRAW); // one full-screen triangle
  const a=gl.getAttribLocation(pg,'p');gl.enableVertexAttribArray(a);gl.vertexAttribPointer(a,2,gl.FLOAT,false,0,0);
  const U={};['R','P','T','M','B','C0','C1','C2','C3','W'].forEach(k=>U[k]=gl.getUniformLocation(pg,k));
  const wc=[1,1,1],wt=[1,1,1]; // per-plume emphasis (Solutions): eased toward the selected scope
  const pal=SX_PAL[sec.id];['C0','C1','C2','C3'].forEach((k,i)=>gl.uniform3fv(U[k],pal[i]));gl.uniform1f(U.M,mode);
  const reduce=matchMedia('(prefers-reduced-motion: reduce)').matches;
  let vis=false,raf=0,last=0,T=8,B=0,px=.5,py=.5,tx=.5,ty=.5,sy=scrollY;
  const frame=now=>{raf=0;const dt=last?Math.min(.05,(now-last)/1000):0;last=now;if(!reduce)T+=dt;B*=.965;
    px+=(tx-px)*.035;py+=(ty-py)*.035;
    let moving=false;for(let i=0;i<3;i++){wc[i]+=(wt[i]-wc[i])*(reduce?1:.04);if(Math.abs(wt[i]-wc[i])>.002)moving=true}
    // soft fields render at half resolution: no visible difference, a quarter of the work
    const w=Math.max(1,Math.round(host.clientWidth*.5)),h=Math.max(1,Math.round(host.clientHeight*.5));
    if(cv.width!==w||cv.height!==h){cv.width=w;cv.height=h;gl.viewport(0,0,w,h)}
    gl.uniform2f(U.R,w,h);gl.uniform2f(U.P,px,py);gl.uniform1f(U.T,T);gl.uniform1f(U.B,B);gl.uniform3f(U.W,wc[0],wc[1],wc[2]);gl.drawArrays(gl.TRIANGLES,0,3);
    cv.classList.add('on');
    if((!reduce||moving)&&vis&&!document.hidden)raf=requestAnimationFrame(frame);else last=0};
  const kick=()=>{if(!raf)raf=requestAnimationFrame(frame)};
  new IntersectionObserver(([e])=>{vis=e.isIntersecting;kick()}).observe(sec);
  document.addEventListener('visibilitychange',kick);new ResizeObserver(kick).observe(host);
  sec.addEventListener('pointermove',e=>{const b=host.getBoundingClientRect();tx=(e.clientX-b.left)/b.width;ty=1-(e.clientY-b.top)/b.height});
  sec.addEventListener('pointerleave',()=>{tx=.5;ty=.5});
  addEventListener('scroll',()=>{const d=Math.abs(scrollY-sy);sy=scrollY;if(vis&&!reduce)T+=Math.min(d,120)*.004},{passive:true}); // scrolling stirs it, like turning a page
  sec.addEventListener('sx:breath',()=>{B=1;kick()});
  kick();
  return{focus(i){for(let k=0;k<3;k++)wt[k]=k===i?1:.25;kick()}}}
sxField($('#insights'),0);sxField($('#team'),1);
// Solutions: three emission plumes; whichever scope the bento shows (clicked or autoplayed) swells, the others quiet down.
// Reads the bento's own tab state (aria-selected) without touching its code.
{const sol=$('#solutions'),f=sxField(sol,2),bento=$('#scopeBento');
 if(f&&bento){const sync=()=>{const t=bento.querySelector('[role=tab][aria-selected="true"]');if(t)f.focus(+t.dataset.s-1)};
   new MutationObserver(sync).observe(bento,{subtree:true,attributes:true,attributeFilter:['aria-selected']});sync()}}

/* ---------- Pricing field: each edition's card stands on its own step, rising short → middle → tall (up to 5 facilities →
   up to 20 → unlimited). Steps are drawn on the gradient panel; hovering or focusing a plan lifts its step a little. ---------- */
{const sec=$('#pricing'),field=sec.querySelector('.pr-field'),cv=field.querySelector('canvas'),ctx=cv.getContext('2d'),reduce=matchMedia('(prefers-reduced-motion: reduce)').matches;
 const STEP=['rgba(242,246,251,.9)','rgba(238,246,236,.9)','rgba(253,246,230,.92)'], // pale paper versions of sky · sage · ochre
       CAP=['#9fb6d3','#93b39a','#dcb468'];                                          // each step's top edge, in the plan's own colour
 const ease=x=>1-Math.pow(1-Math.min(1,Math.max(0,x)),3),lift=[0,0,0];
 let L=null,t0=-1,W=0,H=0,hot=-1,raf=0;
 // positions are measured from the panel itself (it is inset from the section), so steps sit exactly under their cards
 const layout=()=>{const pr=Math.min(devicePixelRatio||1,2),f=field.getBoundingClientRect();W=field.offsetWidth;H=field.offsetHeight;
   cv.width=W*pr;cv.height=H*pr;ctx.setTransform(pr,0,0,pr,0,0);L=null;
   const rel=el=>{const e=el.getBoundingClientRect();return{l:e.left-f.left,t:e.top-f.top,r:e.right-f.left,b:e.bottom-f.top}};
   const cards=[...sec.querySelectorAll('.pflip')].map(rel),head=rel(sec.querySelector('.head'));
   if(cards.length===3&&cards[1].l-cards[0].l>40)L={cards,head}}; // stacked cards (phones): the panel carries the gradient alone
 const draw=now=>{ctx.clearRect(0,0,W,H);if(!L)return false;const t=reduce?99:t0<0?-1:(now-t0)/1000;
   if(t<0)return t0>=0; // a frame's timestamp can land just before t0: wait a frame rather than stop
   let busy=false;
   L.cards.forEach((c,i)=>{const k=ease((t-i*.2)/1);if(k<1)busy=true;if(!k)return;
     const want=hot===i?1:0;lift[i]+=(want-lift[i])*(reduce?1:.14);if(Math.abs(want-lift[i])>.002)busy=true;
     // the rises share the room between the intro text and the cards (short, middle, tall); a hovered plan lifts 14px
     const room=Math.max(30,c.t-(L.head.b+8)),top=Math.max(L.head.b+4,c.t-room*[.3,.65,1][i]-14*lift[i]),
           y=H-(H-top)*k,x=c.l-22,w=c.r-c.l+44;
     ctx.fillStyle=STEP[i];ctx.beginPath();ctx.roundRect(x,y,w,H-y+2,[18,18,0,0]);ctx.fill();
     ctx.save();ctx.clip();ctx.globalAlpha=.55+.45*lift[i];ctx.fillStyle=CAP[i];ctx.fillRect(x,y,w,3);ctx.restore()});
   return busy};
 const tick=now=>{raf=0;if(draw(now)&&!reduce)kick()},kick=()=>{if(!raf)raf=requestAnimationFrame(tick)};
 sec.querySelectorAll('.pflip').forEach((p,i)=>{const on=()=>{hot=i;kick()},off=()=>{if(hot===i){hot=-1;kick()}};
   p.addEventListener('pointerenter',on);p.addEventListener('pointerleave',off);
   p.addEventListener('focusin',on);p.addEventListener('focusout',e=>{if(!p.contains(e.relatedTarget))off()})});
 layout();
 new ResizeObserver(()=>{layout();draw(performance.now())}).observe(sec);
 // the steps rise once, edition by edition, when the section comes into view (after the cards' own reveal settles)
 new IntersectionObserver(([e],io)=>{if(!e.isIntersecting)return;io.disconnect();
   setTimeout(()=>{layout();t0=performance.now();kick()},700)},{threshold:.25}).observe(sec)}

/* ---------- Deep dive accordion ---------- */
const ACC=[
 ['ESG reporting and GHG accounting: how to be audit ready','Continuous capture, evidence, and defensible outputs',['Focus on structured capture of activity data and attach verifiable evidence to every claim. audit ready reporting requires traceable transformations and versioned exports auditors can follow.','Our approach builds immutable logging, reviewer approvals, and export formats that align with common assurance workflows so audit time is spent on judgment not data-chasing.']],
 ['Audit ready logging and evidence','Immutable trails, attachments, and auditor-friendly exports',['An append only logging model with linked evidence reduces auditor friction. Each activity record records who submitted, who reviewed, and what evidence was attached all exportable alongside the numbers.','This enables faster assurance cycles and increases confidence in reported totals across financial and sustainability audiences.']],
 ['Role based auth & approval workflows','Segregation of duties for reliable operational data',['Implement clear roles submitter, validator, approver and configurable approval queues. Activity submissions can be rejected with comments and routed back for correction, preserving history.','These controls reduce accidental misreporting and provide governance evidence for audits and executive reviews.']],
 ['Fuel, electricity & energy activities','Meters, invoices, normalization and exception handling',['Capture fuel and electricity activities at meter granularity or via invoices, normalize units, and flag anomalies for review. Reconciliation helps you close the gap between operational records and reported totals.','Built-in validators and mappings let operations teams resolve issues early while keeping the accounting team confident in aggregated results.']]];
{const list=$('#lrList'),pane=$('#lrPane');let cur=0,restart=()=>{};
 const arrow='<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.25" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M5 12h14M13 6l6 6-6 6"/></svg>';
 list.innerHTML=ACC.map(([t,s],i)=>`<button type="button" role="tab" id="lrt${i}" aria-controls="lrPane"><b>${t}</b><span>${s}</span></button>`).join('');
 const tabs=[...list.children];
 const show=(i,focus)=>{cur=i;const[t,s,ps]=ACC[i],next=ACC[(i+1)%ACC.length][0];
   tabs.forEach((b,j)=>{b.setAttribute('aria-selected',j===i);b.tabIndex=j===i?0:-1});if(focus)tabs[i].focus();
   pane.setAttribute('aria-labelledby','lrt'+i);
   pane.innerHTML=`<div class="swap"><div class="lr-meta">${Math.max(1,Math.round(ps.join(' ').split(/\s+/).length/200))} min read</div>
     <h3>${t}</h3><p class="lr-stand">${s}</p><div class="lr-body">${ps.map(p=>`<p>${p}</p>`).join('')}</div>
     <button type="button" class="lr-next" data-next>Next: ${next}${arrow}</button></div>`;
   restart()};
 restart=ringPlay($('#lrPlay'),()=>show((cur+1)%ACC.length),pane,10000);
 list.onclick=e=>{const b=e.target.closest('[role=tab]');if(b)show(tabs.indexOf(b))};
 list.onkeydown=e=>{const step={ArrowDown:1,ArrowRight:1,ArrowUp:-1,ArrowLeft:-1}[e.key];
   if(step){e.preventDefault();show((cur+step+ACC.length)%ACC.length,true)}
   else if(e.key==='Home'||e.key==='End'){e.preventDefault();show(e.key==='Home'?0:ACC.length-1,true)}};
 pane.onclick=e=>{if(e.target.closest('[data-next]'))show((cur+1)%ACC.length)};
 show(0)}

